import { Component, computed, inject, resource } from '@angular/core';
import { toSignal } from '@angular/core/rxjs-interop';
import { NgTemplateOutlet } from '@angular/common';
import { ActivatedRoute, Router } from '@angular/router';
import { firstValueFrom } from 'rxjs';
import { ApiService } from '../core/api.service';
import { AUDITORIUM, Cell, cellIds } from '../core/auditorium';
import { BookingService } from '../core/booking.service';
import { showDate } from '../core/dates';
import { Screening } from '../core/models';

export type SeatState = 'available' | 'selected' | 'unavailable' | 'accessible';

const LEGEND: { state: SeatState; label: string }[] = [
  { state: 'available', label: 'Available' },
  { state: 'selected', label: 'Selected' },
  { state: 'unavailable', label: 'Unavailable' },
  { state: 'accessible', label: 'Accessible' },
];

function startColumn(cell: Cell): number {
  return cell.kind === 'seat' ? cell.column : cell.start;
}

function label(cell: Cell): string {
  return cell.kind === 'seat' ? `${cell.column}` : `${cell.start}-${cell.end}`;
}

@Component({
  selector: 'app-seat-map',
  imports: [NgTemplateOutlet],
  templateUrl: './seat-map.component.html',
  styleUrl: './seat-map.component.scss',
})
export class SeatMapComponent {
  private readonly api = inject(ApiService);
  private readonly router = inject(Router);
  private readonly route = inject(ActivatedRoute);
  private readonly params = toSignal(this.route.paramMap, { requireSync: true });
  readonly booking = inject(BookingService);

  readonly rows = AUDITORIUM;
  readonly legend = LEGEND;

  readonly data = resource({
    params: () => Number(this.params().get('id')),
    loader: async ({ params: id }) => {
      try {
        const screening = await firstValueFrom(this.api.screening(id));
        await firstValueFrom(this.api.movie(screening.movieId));
        this.booking.begin(id);
        return { screening, occupied: new Set(screening.occupiedSeats) };
      } catch {
        await this.router.navigate(['/']);
        return undefined;
      }
    },
  });

  readonly selectedRows = computed(() => {
    const byRow = new Map<number, Cell[]>();
    for (const cell of this.booking.seats()) {
      byRow.set(cell.row, [...(byRow.get(cell.row) ?? []), cell]);
    }
    return [...byRow.entries()]
      .sort(([a], [b]) => a - b)
      .map(([row, cells]) => ({
        row,
        text: [...cells]
          .sort((a, b) => startColumn(a) - startColumn(b))
          .map(label)
          .join(', '),
      }));
  });

  dateLabel(screening: Screening): string {
    return showDate(screening.date, screening.time);
  }

  stateOf(cell: Cell, occupied: Set<string>): SeatState {
    if (cellIds(cell).some((id) => occupied.has(id))) {
      return 'unavailable';
    }
    if (this.booking.isSelected(cell)) {
      return 'selected';
    }
    return cell.kind === 'seat' && cell.accessible ? 'accessible' : 'available';
  }

  onCellClick(cell: Cell, occupied: Set<string>): void {
    if (this.stateOf(cell, occupied) !== 'unavailable') {
      this.booking.toggle(cell);
    }
  }
}

@if (data.value(); as value) {
  <main class="page">
    <h1 data-testid="seat-map-title">Choose your seats</h1>
    <p data-testid="seat-map-subtitle">Show Date: {{ dateLabel(value.screening) }}</p>
    <p class="limit" data-testid="seat-limit-info">You can reserve up to 10 seats per reservation</p>

    <div class="screen" data-testid="screen-indicator">SCREEN</div>

    <div class="auditorium" data-testid="seat-map">
      @for (row of rows; track row.row) {
        <div class="row" data-testid="seat-row" [attr.data-row]="row.row">
          <span class="row-label" data-testid="row-label-left" [attr.data-row]="row.row">{{ row.row }}</span>
          @if (row.left) {
            <div class="block outer">
              <ng-container *ngTemplateOutlet="cellsTpl; context: { $implicit: row.left, occupied: value.occupied }" />
            </div>
          } @else {
            <div class="entrance"></div>
          }
          <div class="aisle" data-testid="aisle" [attr.data-row]="row.row"></div>
          <div class="block middle">
            <ng-container *ngTemplateOutlet="cellsTpl; context: { $implicit: row.middle, occupied: value.occupied }" />
          </div>
          <div class="aisle" data-testid="aisle" [attr.data-row]="row.row"></div>
          <div class="block outer">
            <ng-container *ngTemplateOutlet="cellsTpl; context: { $implicit: row.right, occupied: value.occupied }" />
          </div>
          <span class="row-label" data-testid="row-label-right" [attr.data-row]="row.row">{{ row.row }}</span>
        </div>
      }
    </div>

    <section class="legend" data-testid="legend">
      @for (item of legend; track item.state) {
        <span class="legend-item" data-testid="legend-item" [attr.data-state]="item.state">
          <span class="swatch"></span>{{ item.label }}
        </span>
      }
    </section>

    <section class="selected-panel" data-testid="selected-seats">
      <p data-testid="selected-seats-count">Selected seats: {{ booking.seatCount() }}</p>
      @for (line of selectedRows(); track line.row) {
        <p data-testid="selected-seats-row" [attr.data-row]="line.row">Row {{ line.row }}: {{ line.text }}</p>
      }
    </section>
  </main>
}

<ng-template #cellsTpl let-cells let-occupied="occupied">
  @for (cell of cells; track $index) {
    @if (cell.kind === 'couch') {
      <button
        type="button"
        class="couch"
        data-testid="couch"
        [attr.data-row]="cell.row"
        [attr.data-column-start]="cell.start"
        [attr.data-column-end]="cell.end"
        [attr.data-state]="stateOf(cell, occupied)"
        (click)="onCellClick(cell, occupied)"
      >{{ cell.start }}-{{ cell.end }}</button>
    } @else {
      <button
        type="button"
        class="seat"
        data-testid="seat"
        [attr.data-row]="cell.row"
        [attr.data-column]="cell.column"
        [attr.data-state]="stateOf(cell, occupied)"
        (click)="onCellClick(cell, occupied)"
      >{{ cell.column }}</button>
    }
  }
</ng-template>

